      // FileViewer instead of bubbling the click as a plain link.
      const linkBlocks = [...this.$el.querySelectorAll('a')]
        .filter(a => !a.classList.contains('file-link'))
      linkBlocks.forEach(a => a.onclick = ev => {
        ev.preventDefault()
