    // every render (v-html), so per-element handlers would go stale.
    captureFileLinks() {
      if (this._fileLinkHandler) return
      this._fileLinkHandler = ev => {
        const link = ev.target?.closest?.('.file-link')
        if (!link || !this.$el.contains(link)) return
        ev.preventDefault()
